window.MOTIF_CATALOG_CHUNKS[18]={"cards":[{"id":"ML-T01839","row_version":3,"title":"미장센·세트","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"group","parent_id":"ML-F22","tag_path":[],"summary":"세트와 소품, 인물의 배치처럼 화면 안에 보이는 요소를 선택하고 조직해 장면의 의미와 분위기를 만드는 방식이다. 작품을 적용할 때는 이야기 속 장소 자체와 그 장소를 화면에 구성한 연출을 구분한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"미장센·세트","entry_url":"cards/ML-T01839/index.html"},{"id":"ML-T01840","row_version":3,"title":"빈 공간 강조","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01839","tag_path":[],"summary":"인물이나 물건을 드물게 두고 비어 있는 영역을 크게 보여 주어 고독, 긴장, 규모감 등을 부각한다. 단순히 배경이 넓은 장면이 아니라 여백의 크기와 배치가 인물이나 상황의 인상에 영향을 주는지 살핀다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"빈 공간 강조","entry_url":"cards/ML-T01840/index.html"},{"id":"ML-T01841","row_version":3,"title":"밀집된 공간","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01839","tag_path":[],"summary":"인물과 사물, 구조물을 좁은 공간에 빽빽하게 배치해 압박감이나 혼잡함을 만든다. 등장 요소가 많다는 사실만으로 분류하지 말고, 공간의 밀도가 장면의 감각이나 관계를 형성하는지 확인한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"밀집된 공간","entry_url":"cards/ML-T01841/index.html"},{"id":"ML-T01842","row_version":4,"title":"대칭 공간","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01839","tag_path":[],"summary":"공간의 좌우나 앞뒤 요소를 서로 대응하도록 배치해 질서와 균형을 만든다. 건축 구조의 대칭성이 아니라 장면에서 공간 구성이 시각적으로 대응하는지를 기준으로 삼는다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"대칭 공간","entry_url":"cards/ML-T01842/index.html"},{"id":"ML-T01843","row_version":2,"title":"위계적 공간","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01839","tag_path":[],"summary":"공간의 크기, 접근성, 자리의 높낮이나 중심성으로 인물과 집단 사이의 권한 차이를 드러낸다. 공간에 차이가 있다는 점보다 그 차이가 누가 지시하고 누가 따르는지를 읽게 하는지 살핀다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"위계적 공간","entry_url":"cards/ML-T01843/index.html"},{"id":"ML-T01844","row_version":2,"title":"반복되는 방","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01839","tag_path":[],"summary":"비슷하거나 동일한 구조의 방이 되풀이되어 공간의 규칙성, 폐쇄감 또는 미로 같은 인상을 만든다. 여러 방이 등장하는 것만으로는 부족하며, 방의 반복이 시각적 패턴이나 경험의 혼란을 형성해야 한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"반복되는 방","entry_url":"cards/ML-T01844/index.html"},{"id":"ML-T01845","row_version":2,"title":"소품으로 성격 제시","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01839","tag_path":[],"summary":"인물이 사용하거나 소유한 물건의 선택과 상태를 통해 성향, 습관, 가치관을 간접적으로 보여 준다. 소품이 단순한 장식이나 사건의 도구인지, 인물에 관한 정보를 전달하는지도 구별한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"소품으로 성격 제시","entry_url":"cards/ML-T01845/index.html"},{"id":"ML-T01846","row_version":3,"title":"공간의 변화","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01839","tag_path":[],"summary":"장면이 진행되며 공간의 구조, 상태, 기능이 달라져 상황이나 관계의 변화를 시각화한다. 장소가 바뀌는 일과 같은 장소 자체가 변하는 일을 구분하고, 변화가 연출에 어떤 역할을 하는지 본다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"공간의 변화","entry_url":"cards/ML-T01846/index.html"},{"id":"ML-T01847","row_version":2,"title":"미장센·의상·분장","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"group","parent_id":"ML-F22","tag_path":[],"summary":"의상과 분장으로 인물의 외양을 구성해 시대, 역할, 상태, 개성을 화면에 나타낸다. 배우의 외모나 신체 자체를 가리키는 것이 아니라 작품을 위해 선택·조정한 외형 표현을 기준으로 한다.","accent":"#688397","tab":"#778F70","facet":"시각·공간 연출","bookmark":"미장센·의상·분장","entry_url":"cards/ML-T01847/index.html"},{"id":"ML-T01848","row_version":2,"title":"색으로 인물 구별","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01847","tag_path":[],"summary":"인물마다 다른 색을 반복적으로 부여해 화면에서 서로를 쉽게 구별하거나 특정 인상을 연결한다. 우연히 색이 다른 경우보다 색의 배정이 인물 식별이나 의미 형성에 꾸준히 기여하는지를 본다.","accent":"#688397","tab":"#778F70","facet":"시각·공간 연출","bookmark":"색으로 인물 구별","entry_url":"cards/ML-T01848/index.html"},{"id":"ML-T01849","row_version":2,"title":"제복으로 소속 표시","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01847","tag_path":[],"summary":"비슷한 형태의 제복을 입혀 인물의 조직, 직책, 소속 집단을 시각적으로 표시한다. 일반적인 의상 통일과 구별해, 복장이 소속이나 권한을 알아보게 하는 기능을 하는지 확인한다.","accent":"#688397","tab":"#778F70","facet":"시각·공간 연출","bookmark":"제복으로 소속 표시","entry_url":"cards/ML-T01849/index.html"},{"id":"ML-T01850","row_version":2,"title":"변장 의상","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01847","tag_path":[],"summary":"인물이 정체나 소속을 숨기거나 다른 사람처럼 보이기 위해 의상을 바꿔 입는다. 단순한 옷차림의 변화가 아니라 타인의 인식이나 인물의 역할을 바꾸려는 목적이 있는지 기준으로 삼는다.","accent":"#688397","tab":"#778F70","facet":"시각·공간 연출","bookmark":"변장 의상","entry_url":"cards/ML-T01850/index.html"},{"id":"ML-T01851","row_version":2,"title":"의상 변화","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01847","tag_path":[],"summary":"이야기의 시간이나 인물의 상황에 따라 의상이 달라져 변화의 흐름을 드러낸다. 의상 교체 자체보다 그 차이가 시간 경과, 역할 변화, 감정 상태 등 읽을 정보를 제공하는지 살핀다.","accent":"#688397","tab":"#778F70","facet":"시각·공간 연출","bookmark":"의상 변화","entry_url":"cards/ML-T01851/index.html"},{"id":"ML-T01852","row_version":2,"title":"상처 분장","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01847","tag_path":[],"summary":"상처의 모양과 색을 피부에 표현해 부상이나 폭력의 흔적을 시각적으로 전달한다. 실제 상처나 대사로만 언급된 부상과 구별해, 분장이 화면에 보이는 흔적을 구성하는 경우에 적용한다.","accent":"#688397","tab":"#778F70","facet":"시각·공간 연출","bookmark":"상처 분장","entry_url":"cards/ML-T01852/index.html"},{"id":"ML-T01853","row_version":3,"title":"가면 사용","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01847","tag_path":[],"summary":"얼굴이나 정체를 가리는 가면을 사용해 인물의 익명성, 역할, 위협감 또는 상징성을 만든다. 얼굴을 가리는 천이나 분장 전반과 혼동하지 말고, 가면이 장면에서 수행하는 기능을 확인한다.","accent":"#688397","tab":"#778F70","facet":"시각·공간 연출","bookmark":"가면 사용","entry_url":"cards/ML-T01853/index.html"},{"id":"ML-T01854","row_version":2,"title":"외형의 점진적 변형","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01847","tag_path":[],"summary":"시간이 흐르거나 사건이 누적되면서 인물의 얼굴, 몸, 복장 등 외형이 단계적으로 달라진다. 한 번의 변장이나 즉각적인 변신과 구분해, 변화가 점진적으로 드러나며 과정 자체가 의미를 갖는지 본다.","accent":"#688397","tab":"#778F70","facet":"시각·공간 연출","bookmark":"외형의 점진적 변형","entry_url":"cards/ML-T01854/index.html"},{"id":"ML-T01855","row_version":3,"title":"미장센·배치·동선","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"group","parent_id":"ML-F22","tag_path":[],"summary":"화면 안의 인물과 사물의 위치, 간격, 이동 경로를 조절해 관계와 시선의 흐름을 구성한다. 단순한 동작 묘사보다 배치나 이동이 장면의 권력 관계, 거리감, 주목점을 형성하는지를 기준으로 한다.","accent":"#688397","tab":"#8B739C","facet":"시각·공간 연출","bookmark":"미장센·배치·동선","entry_url":"cards/ML-T01855/index.html"},{"id":"ML-T01856","row_version":2,"title":"중앙 배치","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01855","tag_path":[],"summary":"인물이나 사물을 화면 또는 공간의 중심에 놓아 시선을 집중시키고 중요도를 부각한다. 중심에 있다는 위치만으로 판단하지 말고, 주변 요소와의 관계가 주목이나 권위를 만들어 내는지 살핀다.","accent":"#688397","tab":"#8B739C","facet":"시각·공간 연출","bookmark":"중앙 배치","entry_url":"cards/ML-T01856/index.html"},{"id":"ML-T01857","row_version":4,"title":"주변부 배치","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01855","tag_path":[],"summary":"인물이나 사물을 화면의 가장자리나 주변 공간에 두어 주변화, 거리감, 관찰자의 위치 등을 드러낸다. 화면 가장자리에 우연히 걸린 장면보다 주변부 배치가 인물의 존재감이나 관계를 좌우하는 경우에 적용한다.","accent":"#688397","tab":"#8B739C","facet":"시각·공간 연출","bookmark":"주변부 배치","entry_url":"cards/ML-T01857/index.html"},{"id":"ML-T01858","row_version":4,"title":"고립된 인물 배치","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01855","tag_path":[],"summary":"인물을 다른 인물이나 사물과 떨어뜨려 놓아 단절, 취약함, 소외감을 시각적으로 드러낸다. 인물이 혼자 등장하는 장면 모두가 아니라, 주변과의 물리적·시각적 분리가 강조되는지 본다.","accent":"#688397","tab":"#8B739C","facet":"시각·공간 연출","bookmark":"고립된 인물 배치","entry_url":"cards/ML-T01858/index.html"},{"id":"ML-T01859","row_version":2,"title":"군중 속 인물 배치","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01855","tag_path":[],"summary":"군중 안에 인물을 배치해 집단에 섞이거나 묻히는 상태, 또는 군중과의 대비를 보여 준다. 사람이 많이 등장하는 것만으로는 해당하지 않으며, 인물과 군중의 배치 관계가 읽히는지 확인한다.","accent":"#688397","tab":"#8B739C","facet":"시각·공간 연출","bookmark":"군중 속 인물 배치","entry_url":"cards/ML-T01859/index.html"},{"id":"ML-T01860","row_version":3,"title":"높낮이로 위계 표현","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01855","tag_path":[],"summary":"단상, 계단, 의자 등 높이 차이를 활용해 인물 사이의 권위나 취약함을 시각적으로 표현한다. 지형상 고저 차이와 구분해, 높낮이가 장면에서 관계나 지위의 의미를 띠는지 본다.","accent":"#688397","tab":"#8B739C","facet":"시각·공간 연출","bookmark":"높낮이로 위계 표현","entry_url":"cards/ML-T01860/index.html"},{"id":"ML-T01861","row_version":2,"title":"접근 동선","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01855","tag_path":[],"summary":"인물이 다른 인물이나 대상, 공간을 향해 다가가는 경로를 연출해 관심, 대면, 위협 또는 결속을 드러낸다. 단순한 이동이 아니라 접근의 방향과 속도, 상대의 반응이 관계를 표현하는지 살핀다.","accent":"#688397","tab":"#8B739C","facet":"시각·공간 연출","bookmark":"접근 동선","entry_url":"cards/ML-T01861/index.html"},{"id":"ML-T01862","row_version":3,"title":"이탈 동선","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01855","tag_path":[],"summary":"인물이 특정 인물이나 장소에서 멀어지거나 장면을 벗어나는 경로를 통해 거부, 회피, 단절, 해방 등을 표현한다. 화면에서 이동하는 모든 경우가 아니라 이탈의 방향과 대상이 장면의 의미에 기여하는 경우에 적용한다.","accent":"#688397","tab":"#8B739C","facet":"시각·공간 연출","bookmark":"이탈 동선","entry_url":"cards/ML-T01862/index.html"},{"id":"ML-T01863","row_version":3,"title":"조명·색채","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"group","parent_id":"ML-F22","tag_path":[],"summary":"빛의 방향과 세기, 색의 선택 및 조합으로 화면의 분위기와 시각적 강조점을 조절한다. 조명과 색채가 단지 화면을 밝히거나 꾸미는 수준인지, 장면의 인상이나 정보 전달을 조직하는지 구분한다.","accent":"#688397","tab":"#A58A4E","facet":"시각·공간 연출","bookmark":"조명·색채","entry_url":"cards/ML-T01863/index.html"},{"id":"ML-T01864","row_version":2,"title":"하이키 조명","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01863","tag_path":[],"summary":"화면 전반을 밝게 비추고 그림자를 약하게 해 개방적이거나 명료한 인상을 만드는 조명 방식이다. 밝은 장면이라는 이유만으로 붙이지 말고, 조명 대비가 낮고 어두운 영역이 제한적인지 살핀다.","accent":"#688397","tab":"#A58A4E","facet":"시각·공간 연출","bookmark":"하이키 조명","entry_url":"cards/ML-T01864/index.html"},{"id":"ML-T01865","row_version":3,"title":"로우키 조명","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01863","tag_path":[],"summary":"빛을 제한해 어두운 영역과 그림자를 크게 남기며 긴장감이나 불확실성을 만드는 조명 방식이다. 단순히 밤에 벌어지는 장면과 구별해, 화면의 밝은 면과 어두운 면의 배치가 연출 효과를 내는지 확인한다.","accent":"#688397","tab":"#A58A4E","facet":"시각·공간 연출","bookmark":"로우키 조명","entry_url":"cards/ML-T01865/index.html"},{"id":"ML-T01866","row_version":2,"title":"역광","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01863","tag_path":[],"summary":"광원을 인물이나 사물 뒤쪽에 두어 윤곽을 강조하거나 앞면을 어둡게 만든다. 화면에 밝은 배경이 있다는 것만으로는 충분하지 않으며, 빛이 피사체의 뒤에서 오는 구도가 확인되어야 한다.","accent":"#688397","tab":"#A58A4E","facet":"시각·공간 연출","bookmark":"역광","entry_url":"cards/ML-T01866/index.html"},{"id":"ML-T01867","row_version":2,"title":"측광","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01863","tag_path":[],"summary":"피사체의 옆에서 빛을 비춰 한쪽 면은 밝고 반대쪽은 어둡게 드러낸다. 얼굴이나 물체에 음영이 있다는 사실보다 측면에서 온 빛이 입체감이나 대비를 만드는지를 기준으로 한다.","accent":"#688397","tab":"#A58A4E","facet":"시각·공간 연출","bookmark":"측광","entry_url":"cards/ML-T01867/index.html"},{"id":"ML-T01868","row_version":2,"title":"실루엣","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01863","tag_path":[],"summary":"밝은 배경에 비해 피사체를 어둡게 표현해 세부보다 외곽 윤곽이 먼저 보이게 한다. 어두운 인물 묘사와 구분해, 형태의 내부 정보가 줄고 윤곽선이 시각적 초점이 되는지 살핀다.","accent":"#688397","tab":"#A58A4E","facet":"시각·공간 연출","bookmark":"실루엣","entry_url":"cards/ML-T01868/index.html"},{"id":"ML-T01869","row_version":3,"title":"명암 대비","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01863","tag_path":[],"summary":"밝은 부분과 어두운 부분을 강하게 맞세워 형태, 시선, 분위기의 차이를 두드러지게 한다. 장면에 자연스러운 그림자가 있는 정도가 아니라 명암 차이가 구성이나 감정 전달에 핵심적인지 본다.","accent":"#688397","tab":"#A58A4E","facet":"시각·공간 연출","bookmark":"명암 대비","entry_url":"cards/ML-T01869/index.html"},{"id":"ML-T01870","row_version":2,"title":"제한된 색상","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01863","tag_path":[],"summary":"화면에 쓰는 색의 종류를 제한해 통일된 분위기나 시각적 규칙을 만든다. 특정 색 하나를 강조하는 방식과 구분해, 전체 팔레트가 의도적으로 좁게 유지되는지 확인한다.","accent":"#688397","tab":"#A58A4E","facet":"시각·공간 연출","bookmark":"제한된 색상","entry_url":"cards/ML-T01870/index.html"},{"id":"ML-T01871","row_version":2,"title":"강조색 사용","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01863","tag_path":[],"summary":"주변 색과 구별되는 특정 색을 제한된 지점에 사용해 시선이나 의미를 모은다. 화면에 선명한 색이 있다는 사실보다 그 색이 다른 요소와 대비되어 반복 가능한 강조 기능을 하는지 기준으로 삼는다.","accent":"#688397","tab":"#A58A4E","facet":"시각·공간 연출","bookmark":"강조색 사용","entry_url":"cards/ML-T01871/index.html"},{"id":"ML-T01872","row_version":2,"title":"색온도 대비","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01863","tag_path":[],"summary":"따뜻한 빛과 차가운 빛을 한 장면이나 인접한 영역에 대비시켜 공간감, 시간감, 정서적 차이를 만든다. 색 자체의 대비와 구별해, 조명 색의 온도 차이가 시각적으로 작동하는지 살핀다.","accent":"#688397","tab":"#A58A4E","facet":"시각·공간 연출","bookmark":"색온도 대비","entry_url":"cards/ML-T01872/index.html"},{"id":"ML-T01873","row_version":3,"title":"구도·화면 크기","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"group","parent_id":"ML-F22","tag_path":[],"summary":"화면에서 무엇을 얼마나 크게 보여 줄지, 요소를 어디에 둘지 선택해 관객의 주의와 정보량을 조절한다. 화면 비율이나 촬영 장비가 아니라 장면 안의 구도와 피사체 크기를 기준으로 한다.","accent":"#688397","tab":"#528982","facet":"시각·공간 연출","bookmark":"구도·화면 크기","entry_url":"cards/ML-T01873/index.html"},{"id":"ML-T01874","row_version":2,"title":"대칭 구도","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01873","tag_path":[],"summary":"화면의 좌우나 상하 요소를 균형 있게 대응시켜 안정감, 질서, 형식성을 만든다. 대칭적인 장소를 촬영했다는 점과 구분해, 프레임 안의 시각 요소가 실제로 대응하는지 확인한다.","accent":"#688397","tab":"#528982","facet":"시각·공간 연출","bookmark":"대칭 구도","entry_url":"cards/ML-T01874/index.html"},{"id":"ML-T01875","row_version":3,"title":"비대칭 구도","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01873","tag_path":[],"summary":"화면 요소를 한쪽으로 치우치게 두거나 서로 다른 무게로 배치해 긴장, 불균형, 움직임을 만든다. 단순히 중심에서 벗어난 구도가 아니라 그 불균형이 시선이나 장면의 인상에 영향을 주는지 본다.","accent":"#688397","tab":"#528982","facet":"시각·공간 연출","bookmark":"비대칭 구도","entry_url":"cards/ML-T01875/index.html"},{"id":"ML-T01876","row_version":3,"title":"프레임 속 프레임","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01873","tag_path":[],"summary":"문틀, 창문, 거울 같은 화면 안의 경계가 인물이나 장면을 다시 둘러싸도록 구성한다. 사각형 물체가 배경에 있는 경우와 구분해, 안쪽 경계가 시선을 좁히거나 거리감·감금감을 만드는지 살핀다.","accent":"#688397","tab":"#528982","facet":"시각·공간 연출","bookmark":"프레임 속 프레임","entry_url":"cards/ML-T01876/index.html"},{"id":"ML-T01877","row_version":2,"title":"넓은 여백","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01873","tag_path":[],"summary":"인물이나 주요 사물 주변에 넓은 빈 영역을 두어 고립감, 여유, 취약함 또는 공간의 규모를 강조한다. 빈 공간 자체보다 피사체와 여백의 비율 및 위치가 구도에서 의미를 만드는지 기준으로 한다.","accent":"#688397","tab":"#528982","facet":"시각·공간 연출","bookmark":"넓은 여백","entry_url":"cards/ML-T01877/index.html"},{"id":"ML-T01878","row_version":2,"title":"클로즈업","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01873","tag_path":[],"summary":"얼굴이나 세부 대상의 일부를 크게 잡아 표정, 반응, 질감에 관객의 주의를 집중시킨다. 가까이 보이는 장면이라도 피사체의 크기와 프레임 내 점유 정도를 확인하고, 단순한 근접 시점과 구별한다.","accent":"#688397","tab":"#528982","facet":"시각·공간 연출","bookmark":"클로즈업","entry_url":"cards/ML-T01878/index.html"},{"id":"ML-T01879","row_version":3,"title":"미디엄숏","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01873","tag_path":[],"summary":"인물을 허리 안팎까지 담아 표정과 상체 동작, 주변 상황을 함께 보여 주는 화면 크기다. 인물의 전신이 주로 보이는 숏이나 얼굴 중심의 클로즈업과 구별해 프레임의 절단 위치를 살핀다.","accent":"#688397","tab":"#528982","facet":"시각·공간 연출","bookmark":"미디엄숏","entry_url":"cards/ML-T01879/index.html"},{"id":"ML-T01880","row_version":3,"title":"롱숏","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01873","tag_path":[],"summary":"인물의 전신과 주변 공간을 함께 담아 행동과 장소의 관계를 보여 주는 화면 크기다. 인물과 환경이 모두 식별되는지 살피며, 인물이 매우 작게 보여 공간이 우세한 익스트림 롱숏과 구별한다.","accent":"#688397","tab":"#528982","facet":"시각·공간 연출","bookmark":"롱숏","entry_url":"cards/ML-T01880/index.html"},{"id":"ML-T01881","row_version":2,"title":"익스트림 롱숏","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01873","tag_path":[],"summary":"인물을 넓은 풍경이나 장소 안에서 매우 작게 담아 공간의 규모와 인물의 위치를 부각한다. 단순한 롱숏보다 환경이 프레임의 대부분을 차지해 인물이 작게 읽히는지 기준으로 삼는다.","accent":"#688397","tab":"#528982","facet":"시각·공간 연출","bookmark":"익스트림 롱숏","entry_url":"cards/ML-T01881/index.html"},{"id":"ML-T01920","row_version":3,"title":"화면 밖 공간 활용","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01873","tag_path":[],"summary":"프레임에 보이지 않는 영역을 소리, 시선, 움직임, 대사 등으로 존재하게 해 관객이 화면 밖을 상상하거나 의식하도록 한다. 화면 밖을 언급하는 것만으로는 부족하며, 보이지 않는 공간이 장면의 정보나 긴장에 실질적으로 기여하는지 확인한다.","accent":"#688397","tab":"#528982","facet":"시각·공간 연출","bookmark":"화면 밖 공간 활용","entry_url":"cards/ML-T01920/index.html"},{"id":"ML-T01882","row_version":4,"title":"카메라·시점","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"group","parent_id":"ML-F22","tag_path":[],"summary":"카메라를 놓는 높이와 방향, 렌즈가 바라보는 위치를 정해 장면과 인물의 관계를 구성한다. 인물의 주관적 시점과 카메라의 촬영 각도는 구분하고, 화면이 관객에게 부여하는 관찰 위치를 살핀다.","accent":"#688397","tab":"#7D8FA3","facet":"시각·공간 연출","bookmark":"카메라·시점","entry_url":"cards/ML-T01882/index.html"},{"id":"ML-T01883","row_version":3,"title":"아이레벨","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01882","tag_path":[],"summary":"카메라를 피사체의 눈높이에 두어 수평적인 관찰 시점을 만든다. 인물이 화면을 바라보는 높이와 혼동하지 말고, 카메라의 위치가 피사체의 눈높이와 대체로 맞는지 확인한다.","accent":"#688397","tab":"#7D8FA3","facet":"시각·공간 연출","bookmark":"아이레벨","entry_url":"cards/ML-T01883/index.html"},{"id":"ML-T01884","row_version":3,"title":"하이앵글","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01882","tag_path":[],"summary":"카메라를 피사체보다 높은 곳에 두고 아래쪽을 향해 촬영한다. 단순히 위에서 내려다본 그림과 구별해 카메라의 위치와 시선 방향이 하향인지 기준으로 삼는다.","accent":"#688397","tab":"#7D8FA3","facet":"시각·공간 연출","bookmark":"하이앵글","entry_url":"cards/ML-T01884/index.html"},{"id":"ML-T01885","row_version":3,"title":"로앵글","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01882","tag_path":[],"summary":"카메라를 피사체보다 낮게 두고 위쪽을 향해 촬영한다. 피사체가 커 보인다는 인상만으로 판단하지 말고, 실제 카메라의 시선이 아래에서 위로 향하는지 살핀다.","accent":"#688397","tab":"#7D8FA3","facet":"시각·공간 연출","bookmark":"로앵글","entry_url":"cards/ML-T01885/index.html"},{"id":"ML-T01886","row_version":3,"title":"더치 앵글","original":"Dutch Angle","aliases":["Dutch Angle","더치 틸트","기울어진 화면"],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01882","tag_path":[],"summary":"카메라를 수평에서 비스듬히 기울여 불안정하거나 낯선 느낌을 만드는 촬영 구도.","accent":"#688397","tab":"#7D8FA3","facet":"시각·공간 연출","bookmark":"더치 앵글","entry_url":"cards/ML-T01886/index.html"},{"id":"ML-T01887","row_version":4,"title":"버드아이뷰","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01882","tag_path":[],"summary":"높은 위치에서 넓은 공간을 비스듬히 내려다보아 장면의 전체 배치와 관계를 보여 주는 시점이다. 일반적인 하이앵글보다 시야가 넓고 공간 전체를 조망하는 구성이 중심인지 확인한다.","accent":"#688397","tab":"#7D8FA3","facet":"시각·공간 연출","bookmark":"버드아이뷰","entry_url":"cards/ML-T01887/index.html"},{"id":"ML-T01888","row_version":3,"title":"수직 탑다운","original":"","aliases":["90도 탑다운","수직 내려다보기"],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01882","tag_path":[],"summary":"카메라를 피사체 바로 위에 두고 바닥을 향해 수직으로 촬영한다. 높은 곳에서 비스듬히 내려다보는 버드아이뷰와 구별해 카메라 축이 거의 수직인지 기준으로 한다.","accent":"#688397","tab":"#7D8FA3","facet":"시각·공간 연출","bookmark":"수직 탑다운","entry_url":"cards/ML-T01888/index.html"},{"id":"ML-T01889","row_version":3,"title":"주관숏","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01882","tag_path":[],"summary":"주관숏은 카메라의 시야를 인물의 눈으로 설정해 관객이 그 인물이 보는 대상을 직접 보는 듯 구성한다. 인물의 시선이나 위치와 연결되어야 하며, 단순히 인물을 가까이 찍은 화면은 해당하지 않는다.","accent":"#688397","tab":"#7D8FA3","facet":"시각·공간 연출","bookmark":"주관숏","entry_url":"cards/ML-T01889/index.html"},{"id":"ML-T01890","row_version":3,"title":"오버숄더숏","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01882","tag_path":[],"summary":"오버숄더숏은 한 인물의 어깨나 뒷머리를 화면 앞쪽에 두고 맞은편 인물이나 대상을 촬영하는 구도다. 대화 장면에서 공간 관계와 시선 방향을 보여주는지 살피며, 어깨가 우연히 프레임에 걸친 화면과 구별한다.","accent":"#688397","tab":"#7D8FA3","facet":"시각·공간 연출","bookmark":"오버숄더숏","entry_url":"cards/ML-T01890/index.html"},{"id":"ML-T01891","row_version":3,"title":"카메라 이동·광학 운용","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"group","parent_id":"ML-F22","tag_path":[],"summary":"카메라 이동·광학 운용은 촬영 중 카메라 위치나 방향을 움직이거나 렌즈의 화각·초점을 조절해 화면의 시야를 바꾸는 방식이다. 실제 카메라의 이동과 렌즈 조작을 가리키며, 화면 속 대상의 움직임이나 후반 합성 효과와 구분한다.","accent":"#688397","tab":"#A07A87","facet":"시각·공간 연출","bookmark":"카메라 이동·광학 운용","entry_url":"cards/ML-T01891/index.html"},{"id":"ML-T01892","row_version":3,"title":"팬","original":"Pan","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01891","tag_path":[],"summary":"카메라를 한 위치에 둔 채 좌우로 회전시켜 화면이 바라보는 방향을 바꾸는 촬영 기법이다. 인물을 따라가거나 공간을 차례로 드러낼 때 사용한다.","accent":"#688397","tab":"#A07A87","facet":"시각·공간 연출","bookmark":"팬","entry_url":"names/724cc77d2d75c51c/index.html"},{"id":"ML-T01893","row_version":3,"title":"틸트","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01891","tag_path":[],"summary":"틸트는 카메라를 고정한 채 렌즈의 방향을 위아래로 회전해 수직 시야를 훑는 움직임이다. 화면의 높낮이를 따라 시선을 옮기는 경우에 쓰며, 카메라 자체가 위아래로 이동하는 동작과 구별한다.","accent":"#688397","tab":"#A07A87","facet":"시각·공간 연출","bookmark":"틸트","entry_url":"cards/ML-T01893/index.html"},{"id":"ML-T01894","row_version":3,"title":"달리","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01891","tag_path":[],"summary":"달리는 카메라를 지지대나 레일에 얹어 앞뒤 또는 좌우로 이동시키는 촬영 방식이다. 촬영 위치가 실제로 이동해 원근과 대상의 크기 관계가 달라지는지 기준으로 삼으며, 렌즈 줌만으로 가까워 보이게 한 화면은 제외한다.","accent":"#688397","tab":"#A07A87","facet":"시각·공간 연출","bookmark":"달리","entry_url":"cards/ML-T01894/index.html"},{"id":"ML-T01895","row_version":3,"title":"트래킹","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01891","tag_path":[],"summary":"트래킹은 카메라가 인물이나 대상을 따라 이동하며 촬영하는 방식으로, 움직이는 대상과 주변 공간의 관계를 이어 보여준다. 추적 이동이 화면의 핵심인지 확인하고, 고정된 카메라의 팬이나 대상 자체의 이동과 구별한다.","accent":"#688397","tab":"#A07A87","facet":"시각·공간 연출","bookmark":"트래킹","entry_url":"cards/ML-T01895/index.html"},{"id":"ML-T01896","row_version":3,"title":"크레인숏","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01891","tag_path":[],"summary":"크레인숏은 크레인이나 지브 장비로 카메라를 높이 올리거나 내리고 수평 이동까지 결합해 촬영하는 숏이다. 높은 위치와 넓은 이동 범위를 활용한 카메라 움직임을 가리키며, 단순한 고소 촬영이나 드론 촬영을 자동으로 포함하지 않는다.","accent":"#688397","tab":"#A07A87","facet":"시각·공간 연출","bookmark":"크레인숏","entry_url":"cards/ML-T01896/index.html"},{"id":"ML-T01897","row_version":3,"title":"핸드헬드","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01891","tag_path":[],"summary":"핸드헬드는 카메라를 손이나 몸으로 직접 지지해 촬영하면서 미세한 흔들림과 반응성 있는 움직임을 화면에 남기는 방식이다. 흔들림이 촬영 운용에서 비롯되었는지 보며, 후반에 흔들림 효과만 입힌 화면과 구분한다.","accent":"#688397","tab":"#A07A87","facet":"시각·공간 연출","bookmark":"핸드헬드","entry_url":"cards/ML-T01897/index.html"},{"id":"ML-T01898","row_version":3,"title":"줌","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01891","tag_path":[],"summary":"줌은 줌렌즈의 초점거리를 바꿔 카메라 위치를 옮기지 않고 화면의 화각과 피사체 크기를 변화시키는 조작이다. 원근 관계가 유지된 채 시야가 좁아지거나 넓어지는지 확인하며, 카메라가 대상에 다가가는 이동 촬영과 구별한다.","accent":"#688397","tab":"#A07A87","facet":"시각·공간 연출","bookmark":"줌","entry_url":"cards/ML-T01898/index.html"},{"id":"ML-T01899","row_version":4,"title":"고정 카메라","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01891","tag_path":[],"summary":"고정 카메라는 촬영 중 카메라 위치와 방향을 움직이지 않고 장면을 담는 방식이다. 화면의 변화가 인물이나 사물의 움직임에서 생기는지 살피며, 아주 짧은 흔들림이나 정지 화면 효과만으로 분류하지 않는다.","accent":"#688397","tab":"#A07A87","facet":"시각·공간 연출","bookmark":"고정 카메라","entry_url":"cards/ML-T01899/index.html"},{"id":"ML-T01900","row_version":3,"title":"초점·시간 표현","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"group","parent_id":"ML-F22","tag_path":[],"summary":"초점·시간 표현은 초점의 선명한 범위와 영상이 흐르는 속도 또는 멈춤을 조절해 관객의 주의와 시간 감각을 구성하는 연출이다. 초점 조작과 시간 조작이 실제 장면에서 어떤 기능을 하는지 따져, 일반적인 화면 흐림이나 빠른 편집과 구별한다.","accent":"#688397","tab":"#79866C","facet":"시각·공간 연출","bookmark":"초점·시간 표현","entry_url":"cards/ML-T01900/index.html"},{"id":"ML-T01901","row_version":2,"title":"얕은 심도","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01900","tag_path":[],"summary":"얕은 심도는 초점이 선명한 거리 범위를 좁게 설정해 특정 인물이나 물체를 두드러지게 하고 다른 거리의 배경을 흐리게 하는 촬영 특성이다. 초점면 밖의 흐림으로 시선을 제한하는지 확인하며, 초점이 맞지 않은 실수나 후반 블러와 구분한다.","accent":"#688397","tab":"#79866C","facet":"시각·공간 연출","bookmark":"얕은 심도","entry_url":"cards/ML-T01901/index.html"},{"id":"ML-T01902","row_version":2,"title":"깊은 심도","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01900","tag_path":[],"summary":"깊은 심도는 화면 앞쪽부터 먼 배경까지 넓은 거리 범위에 초점이 선명하게 유지되는 촬영 특성이다. 서로 다른 거리의 대상이 동시에 읽히도록 구성되었는지 살피며, 단순히 넓은 풍경을 담았다는 이유만으로 분류하지 않는다.","accent":"#688397","tab":"#79866C","facet":"시각·공간 연출","bookmark":"깊은 심도","entry_url":"cards/ML-T01902/index.html"},{"id":"ML-T01903","row_version":4,"title":"초점 이동","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01900","tag_path":[],"summary":"초점 이동은 한 화면 안에서 초점이 맞는 대상을 바꾸어 관객의 주의를 한 지점에서 다른 지점으로 옮기는 기법이다. 초점면의 변화가 장면의 정보나 관계를 드러내는지 확인하고, 카메라 이동이나 대상의 움직임으로 선명도가 달라진 경우와 구별한다.","accent":"#688397","tab":"#79866C","facet":"시각·공간 연출","bookmark":"초점 이동","entry_url":"cards/ML-T01903/index.html"},{"id":"ML-T01904","row_version":2,"title":"슬로모션","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01900","tag_path":[],"summary":"슬로모션은 촬영 때보다 느린 재생 속도로 움직임을 늘려 순간의 동작과 시간을 강조하는 표현이다. 동작의 지속 시간이 실제보다 길어 보이도록 만들어졌는지 기준으로 삼으며, 느린 동작이나 느린 편집만으로는 해당하지 않는다.","accent":"#688397","tab":"#79866C","facet":"시각·공간 연출","bookmark":"슬로모션","entry_url":"cards/ML-T01904/index.html"},{"id":"ML-T01905","row_version":3,"title":"타임랩스","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01900","tag_path":[],"summary":"타임랩스는 긴 시간 동안 촬영한 장면을 간격을 둔 프레임으로 기록한 뒤 정상 속도로 재생해 시간의 흐름을 압축하는 방식이다. 오랜 변화가 짧은 영상에 빠르게 나타나는지 확인하며, 일반적인 속도 조절이나 짧은 장면의 빠른 편집과 구별한다.","accent":"#688397","tab":"#79866C","facet":"시각·공간 연출","bookmark":"타임랩스","entry_url":"cards/ML-T01905/index.html"},{"id":"ML-T01906","row_version":2,"title":"프리즈프레임","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01900","tag_path":[],"summary":"프리즈프레임은 영상의 한 프레임을 고정해 움직임을 일시적으로 멈춘 듯 보여주는 편집 또는 재생 효과다. 동영상 흐름 중 정지 이미지가 의도적으로 삽입되었는지 살피며, 정지 사진이나 인물의 실제 부동 상태와 구별한다.","accent":"#688397","tab":"#79866C","facet":"시각·공간 연출","bookmark":"프리즈프레임","entry_url":"cards/ML-T01906/index.html"},{"id":"ML-T01907","row_version":2,"title":"장노출 표현","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01900","tag_path":[],"summary":"장노출 표현은 셔터를 오래 열어 한 프레임에 시간에 걸친 빛이나 움직임을 누적해 담는 시각 효과다. 이동 궤적이나 빛의 잔상이 노출 시간의 누적으로 나타나는지 확인하며, 여러 프레임을 합성한 흔적이나 단순한 모션 블러와 구별한다.","accent":"#688397","tab":"#79866C","facet":"시각·공간 연출","bookmark":"장노출 표현","entry_url":"cards/ML-T01907/index.html"},{"id":"ML-T01915","row_version":4,"title":"롱테이크","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01900","tag_path":[],"summary":"롱테이크는 편집으로 끊지 않고 비교적 긴 시간 동안 이어 촬영한 화면이다. 장면 안의 동작과 카메라 운용이 한 번의 연속된 숏으로 진행되는지 기준으로 삼으며, 여러 숏을 매끄럽게 이어 한 번처럼 보이게 한 편집과 구별한다.","accent":"#688397","tab":"#79866C","facet":"시각·공간 연출","bookmark":"롱테이크","entry_url":"cards/ML-T01915/index.html"},{"id":"ML-T01908","row_version":3,"title":"편집·연결","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"group","parent_id":"ML-F22","tag_path":[],"summary":"편집·연결은 촬영된 숏이나 장면을 선택하고 배열해 시간, 공간, 행동, 의미의 관계를 만드는 작업이다. 개별 장면의 촬영 기법이 아니라 화면 사이의 결합 방식과 그 효과를 가리키는지 확인한다.","accent":"#688397","tab":"#AF8665","facet":"시각·공간 연출","bookmark":"편집·연결","entry_url":"cards/ML-T01908/index.html"},{"id":"ML-T01909","row_version":3,"title":"연속 편집","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01908","tag_path":[],"summary":"연속 편집은 숏 사이의 시간과 공간을 자연스럽게 이어 관객이 동작과 장면을 끊김 없이 이해하도록 구성하는 방식이다. 시선 방향, 동작, 화면 방향이 연결의 기준인지 살피며, 시간이나 공간의 단절을 의도적으로 드러내는 편집과 구별한다.","accent":"#688397","tab":"#AF8665","facet":"시각·공간 연출","bookmark":"연속 편집","entry_url":"cards/ML-T01909/index.html"},{"id":"ML-T01910","row_version":3,"title":"교차 편집","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01908","tag_path":[],"summary":"교차 편집은 서로 다른 장소나 행동의 숏을 번갈아 배치해 두 흐름을 함께 진행시키는 편집 방식이다. 번갈아 보여주는 흐름 사이에 동시성이나 긴장 같은 관계가 형성되는지 확인하며, 단지 여러 장면을 차례로 보여주는 편집과 구별한다.","accent":"#688397","tab":"#AF8665","facet":"시각·공간 연출","bookmark":"교차 편집","entry_url":"cards/ML-T01910/index.html"},{"id":"ML-T01911","row_version":3,"title":"평행 편집","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01908","tag_path":[],"summary":"평행 편집은 직접 이어지지 않는 둘 이상의 사건이나 이미지 흐름을 교대로 배치해 주제적·정서적 비교를 만드는 방식이다. 사건이 같은 시간에 일어난다는 전제가 필수는 아니며, 동시 진행을 강조하는 교차 편집과 구분한다.","accent":"#688397","tab":"#AF8665","facet":"시각·공간 연출","bookmark":"평행 편집","entry_url":"cards/ML-T01911/index.html"},{"id":"ML-T01912","row_version":3,"title":"점프컷","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01908","tag_path":[],"summary":"점프컷은 이어지는 한 장면 안에서 시간이나 위치를 불연속적으로 건너뛰어 화면이 튀는 듯한 효과를 만드는 편집이다. 같은 구도나 연속된 행동에서 생략이 눈에 띄는지 살피며, 장소나 관점이 바뀌는 일반적인 컷과 구별한다.","accent":"#688397","tab":"#AF8665","facet":"시각·공간 연출","bookmark":"점프컷","entry_url":"cards/ML-T01912/index.html"},{"id":"ML-T01913","row_version":3,"title":"매치컷","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01908","tag_path":[],"summary":"매치컷은 앞뒤 숏의 형태, 움직임, 색, 소리 또는 의미를 연결해 전환에 연속성이나 연상을 만드는 편집이다. 두 숏 사이의 구체적인 대응 관계가 전환의 효과를 이루는지 확인하며, 단순히 장면이 바뀐 경우와 구별한다.","accent":"#688397","tab":"#AF8665","facet":"시각·공간 연출","bookmark":"매치컷","entry_url":"cards/ML-T01913/index.html"},{"id":"ML-T01914","row_version":2,"title":"몽타주","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01908","tag_path":[],"summary":"몽타주는 여러 숏이나 이미지를 배열하고 결합해 개별 화면만으로는 드러나지 않는 시간의 압축, 연상, 의미를 만드는 편집 구성이다. 배열 자체가 새로운 관계나 관념을 형성하는지 살피며, 빠르게 이어 붙였다는 이유만으로 분류하지 않는다.","accent":"#688397","tab":"#AF8665","facet":"시각·공간 연출","bookmark":"몽타주","entry_url":"cards/ML-T01914/index.html"},{"id":"ML-T01916","row_version":3,"title":"생략 편집","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01908","tag_path":[],"summary":"생략 편집은 이야기의 일부 시간을 건너뛰어 사건의 전후만 남기고 진행을 압축하는 방식이다. 관객이 빠진 시간을 추론할 수 있도록 시간의 공백이 생기는지 확인하며, 연속 동작의 튐을 두드러지게 만드는 점프컷과 구별한다.","accent":"#688397","tab":"#AF8665","facet":"시각·공간 연출","bookmark":"생략 편집","entry_url":"cards/ML-T01916/index.html"},{"id":"ML-T01917","row_version":2,"title":"그래픽·애니메이션","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"group","parent_id":"ML-F22","tag_path":[],"summary":"그래픽·애니메이션은 문자, 도형, 그림이나 움직이는 그래픽을 화면에 배치해 정보나 시각적 동작을 전달하는 연출이다. 화면에 더해진 그래픽 요소가 의미나 움직임을 담당하는지 살피며, 촬영된 사물의 움직임이나 장식적 배경만으로 분류하지 않는다.","accent":"#688397","tab":"#6D7BA1","facet":"시각·공간 연출","bookmark":"그래픽·애니메이션","entry_url":"cards/ML-T01917/index.html"},{"id":"ML-T01918","row_version":3,"title":"분할 화면","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01917","tag_path":[],"summary":"분할 화면은 한 화면을 둘 이상의 영역으로 나누고 각 영역에 서로 다른 영상이나 정보를 동시에 보여주는 구성이다. 나뉜 화면들이 동시성이나 비교를 만들어내는지 확인하며, 장면 전환이나 화면 속 액자처럼 보이는 단일 영상과 구별한다.","accent":"#688397","tab":"#6D7BA1","facet":"시각·공간 연출","bookmark":"분할 화면","entry_url":"cards/ML-T01918/index.html"},{"id":"ML-T01919","row_version":3,"title":"자막 개입","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01917","tag_path":[],"summary":"자막 개입은 자막이나 화면 문구를 대사 표기 이상의 시각 요소로 사용해 장면의 의미, 리듬, 관객의 해석에 영향을 주는 연출이다. 문자가 화면 구성이나 서술에 능동적으로 참여하는지 살피며, 내용을 그대로 옮기는 통상적인 대사 자막과 구별한다.","accent":"#688397","tab":"#6D7BA1","facet":"시각·공간 연출","bookmark":"자막 개입","entry_url":"cards/ML-T01919/index.html"},{"id":"ML-T01921","row_version":2,"title":"과장된 움직임","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01917","tag_path":[],"summary":"과장된 움직임은 인물이나 사물의 동작을 현실적인 크기나 속도보다 크게 변형해 힘, 감정, 반응을 분명히 드러내는 표현이다. 움직임의 과장이 표현 의도로 기능하는지 확인하며, 단순히 빠르거나 큰 동작이라는 이유만으로 분류하지 않는다.","accent":"#688397","tab":"#6D7BA1","facet":"시각·공간 연출","bookmark":"과장된 움직임","entry_url":"cards/ML-T01921/index.html"},{"id":"ML-T01922","row_version":2,"title":"스미어 프레임","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01917","tag_path":[],"summary":"스미어 프레임은 빠른 움직임의 일부 프레임을 늘어나거나 번진 형태로 그려 동작의 속도와 방향을 강조하는 애니메이션 기법이다. 한 프레임의 형상 왜곡이 순간적인 움직임을 잇는지 살피며, 지속적으로 남는 잔상이나 흐림 효과와 구별한다.","accent":"#688397","tab":"#6D7BA1","facet":"시각·공간 연출","bookmark":"스미어 프레임","entry_url":"cards/ML-T01922/index.html"},{"id":"ML-T01923","row_version":3,"title":"스쿼시 앤 스트레치","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01917","tag_path":[],"summary":"스쿼시 앤 스트레치는 움직임에 맞춰 캐릭터나 사물의 형태를 눌렀다가 늘려 탄력과 무게감을 표현하는 애니메이션 원리다. 변형 뒤에도 대상의 부피감과 정체성이 유지되는지 살피며, 형태가 무작위로 찌그러지는 효과와 구별한다.","accent":"#688397","tab":"#6D7BA1","facet":"시각·공간 연출","bookmark":"스쿼시 앤 스트레치","entry_url":"cards/ML-T01923/index.html"},{"id":"ML-T01924","row_version":2,"title":"속도선","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01917","tag_path":[],"summary":"속도선은 선형 그래픽을 화면에 더해 대상의 이동 방향이나 움직임의 빠르기를 강조하는 표현이다. 선이 동작의 궤적이나 속도감을 시각화하는지 확인하며, 배경 무늬나 장식선과 구별한다.","accent":"#688397","tab":"#6D7BA1","facet":"시각·공간 연출","bookmark":"속도선","entry_url":"cards/ML-T01924/index.html"},{"id":"ML-T01925","row_version":4,"title":"화면 흔들림","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":"tag","parent_id":"ML-T01917","tag_path":[],"summary":"화면 흔들림은 카메라 시야나 화면 전체를 흔들어 충격, 불안정, 동요를 전달하는 시각 연출이다. 흔들림이 장면에 의도된 효과로 적용되었는지 살피며, 핸드헬드 촬영의 실제 카메라 움직임과 후반 효과를 구분해 기록한다.","accent":"#688397","tab":"#6D7BA1","facet":"시각·공간 연출","bookmark":"화면 흔들림","entry_url":"cards/ML-T01925/index.html"},{"id":"ML-T01926","row_version":2,"title":"화자·시점","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"group","parent_id":"ML-F23","tag_path":[],"summary":"화자와 시점은 이야기를 전달하는 목소리와 사건을 바라보는 위치를 정해 독자가 얻는 정보의 범위를 좌우한다. 작품을 분류할 때는 누가 말하는지와 누구의 인식에 초점이 맞는지를 나누어 살핀다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"화자·시점","entry_url":"cards/ML-T01926/index.html"},{"id":"ML-T01927","row_version":3,"title":"1인칭 화자","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01926","tag_path":[],"summary":"1인칭 화자는 자신의 경험이나 관점을 ‘나’의 목소리로 전달하며, 서술은 그 화자가 보고 알 수 있는 범위에 놓인다. 인물의 생각을 직접 말하는 대사나 3인칭 서술 속 자기 지칭과는 구별해, 이야기 전달자가 1인칭인지 확인한다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"1인칭 화자","entry_url":"cards/ML-T01927/index.html"},{"id":"ML-T01928","row_version":2,"title":"2인칭 서술","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01926","tag_path":[],"summary":"2인칭 서술은 ‘너’ 또는 ‘당신’을 이야기의 주된 대상이자 행위자로 지목해 사건을 전달한다. 독자에게 말을 거는 표현이 잠깐 나오는 것만으로는 해당하지 않으며, 서술 전반이 2인칭 인물을 구성하는지 본다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"2인칭 서술","entry_url":"cards/ML-T01928/index.html"},{"id":"ML-T01929","row_version":3,"title":"3인칭 제한 시점","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01926","tag_path":[],"summary":"3인칭 제한 시점은 ‘그’ 또는 인물의 이름으로 서술하면서 특정 인물의 지각과 지식에 주로 한정한다. 다른 인물의 속마음이나 그 인물이 알 수 없는 사건까지 서술하는 대목이 지속되는지 살펴 전지적 서술과 구분한다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"3인칭 제한 시점","entry_url":"cards/ML-T01929/index.html"},{"id":"ML-T01930","row_version":2,"title":"전지적 서술","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01926","tag_path":[],"summary":"전지적 서술은 서술자가 여러 인물의 내면과 서로 떨어진 사건, 인물들이 모르는 사실까지 폭넓게 전달하는 방식이다. 한 인물의 생각을 깊게 묘사한다는 이유만으로 전지적이라 하지 말고, 서술의 지식 범위가 인물 하나를 넘어서는지 확인한다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"전지적 서술","entry_url":"cards/ML-T01930/index.html"},{"id":"ML-T01931","row_version":2,"title":"관찰자 시점","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01926","tag_path":[],"summary":"관찰자 시점은 서술자가 인물의 행동과 말처럼 외부에서 관찰 가능한 내용에 집중하고 내면을 직접 확정하지 않는 방식이다. 감정이나 생각을 서술자가 단정하는지, 행동의 단서만 제시하는지를 기준으로 제한 시점과 구별한다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"관찰자 시점","entry_url":"cards/ML-T01931/index.html"},{"id":"ML-T01932","row_version":2,"title":"다중 시점","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01926","tag_path":[],"summary":"다중 시점은 둘 이상의 인물이나 서술자가 각자의 위치에서 사건을 전달해 관점이 바뀌는 구성이다. 한 화자가 여러 인물을 언급하는 것과는 다르므로, 실제로 초점 인식이나 서술 주체가 교대하는지 확인한다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"다중 시점","entry_url":"cards/ML-T01932/index.html"},{"id":"ML-T01933","row_version":2,"title":"비인간 화자","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01926","tag_path":[],"summary":"비인간 화자는 인간이 아닌 존재가 이야기의 전달 목소리를 맡는 경우로, 동물·사물·기계 등 그 존재의 감각과 관점이 서술에 반영된다. 비인간 인물이 등장하거나 말하는 장면만으로는 부족하며, 사건을 전달하는 화자 자체가 비인간인지 살핀다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"비인간 화자","entry_url":"cards/ML-T01933/index.html"},{"id":"ML-T01934","row_version":2,"title":"화자의 신뢰","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"group","parent_id":"ML-F23","tag_path":[],"summary":"화자의 신뢰는 화자의 진술이 사실과 사건의 의미를 얼마나 정확하게 전달하는지에 관한 판단이다. 화자의 성격이 호감 가는지와 혼동하지 말고, 서술 안팎의 증거가 진술을 뒷받침하거나 흔드는지 본다.","accent":"#7C808E","tab":"#778F70","facet":"서술·언어·정보","bookmark":"화자의 신뢰","entry_url":"cards/ML-T01934/index.html"},{"id":"ML-T01935","row_version":2,"title":"신뢰할 수 있는 화자","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01934","tag_path":[],"summary":"신뢰할 수 있는 화자는 사실과 판단을 대체로 정확하고 일관되게 전달해 독자가 진술을 믿을 만한 근거를 제공한다. 화자가 선하거나 친절한 인물인지가 아니라, 서술이 드러난 사건 및 다른 정보와 맞아떨어지는지를 기준으로 삼는다.","accent":"#7C808E","tab":"#778F70","facet":"서술·언어·정보","bookmark":"신뢰할 수 있는 화자","entry_url":"cards/ML-T01935/index.html"},{"id":"ML-T01936","row_version":2,"title":"거짓말하는 화자","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01934","tag_path":[],"summary":"거짓말하는 화자는 자신이 사실이라고 믿는 내용을 전달하면서도 의도적으로 진실과 다른 말을 한다. 착각이나 기억 오류와 구분하려면 화자가 진실을 알고도 감추거나 왜곡한다는 단서가 작품에 있는지 확인한다.","accent":"#7C808E","tab":"#778F70","facet":"서술·언어·정보","bookmark":"거짓말하는 화자","entry_url":"cards/ML-T01936/index.html"},{"id":"ML-T01937","row_version":2,"title":"잘못 알고 있는 화자","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01934","tag_path":[],"summary":"잘못 알고 있는 화자는 정보 부족이나 오해 때문에 사실과 다른 내용을 진심으로 믿고 전달한다. 의도적으로 속이는 화자와 달리 거짓말할 목적은 없으며, 서술이 나중에 그 믿음의 오류를 드러내는지 살핀다.","accent":"#7C808E","tab":"#778F70","facet":"서술·언어·정보","bookmark":"잘못 알고 있는 화자","entry_url":"cards/ML-T01937/index.html"},{"id":"ML-T01938","row_version":2,"title":"자기기만적 화자","original":"","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":"tag","parent_id":"ML-T01934","tag_path":[],"summary":"자기기만적 화자는 자신의 욕망이나 두려움에 맞도록 현실을 해석하면서 자신에게도 진실을 감추거나 축소한다. 단순한 무지나 의식적인 거짓말과 구별해, 말과 행동 또는 확인된 사실 사이의 모순이 자기 인식의 왜곡을 보여주는지 본다.","accent":"#7C808E","tab":"#778F70","facet":"서술·언어·정보","bookmark":"자기기만적 화자","entry_url":"cards/ML-T01938/index.html"}]}.cards;